-- EPIC-163.5: 심연으로의 스크롤 깊이별 색/효과 기본값 시딩(기존에 올린 배경 이미지 URL은 보존). 실행 완료.
update page_modules m set settings = jsonb_set(m.settings, '{depths}', $j$[{"title":"Depth 1 · 문 앞 광장","text":"사일로를 운명적으로 찾아와 준 첫눈 같은 사람들. 따뜻한 광장에서 당신의 취향을 기록해 보세요.","color1":"#FBF6E6","color2":"#F4E58A","accent":"#E4C84B","effects":["stars","feathers"],"imageUrl":"https://pub-c2f2b82ef6164e838c737bb7ed48da65.r2.dev/media/3e54f36a-f204-4860-9626-97af3c56f57d/1790303421362-ca4d584e-989f-4c2c-bf2d-84a00b503c82.webp"},{"title":"Depth 2 · 살롱의 서재","text":"호기심의 열쇠를 쥐고 토끼굴로 뛰어든 탐험가. 굳게 닫혀있던 시대의 지식과 영감의 서랍장이 열립니다.","color1":"#14532D","color2":"#2ECC8F","accent":"#9CF0C4","effects":["fireflies","dust"],"imageUrl":"https://pub-c2f2b82ef6164e838c737bb7ed48da65.r2.dev/media/3e54f36a-f204-4860-9626-97af3c56f57d/1790303522937-61471877-78d7-42d2-8b8a-eaeb6f7fdb85.jpg"},{"title":"Depth 3 · 살롱의 무도회장","text":"낭만과 열정을 수집하는 파티의 주인공. 당신만의 아카이브를 완성하고 찬란한 모임을 즐겨보세요.","color1":"#0047AB","color2":"#0F52BA","accent":"#9FC1FF","effects":["bubbles","stars"],"imageUrl":"https://pub-c2f2b82ef6164e838c737bb7ed48da65.r2.dev/media/3e54f36a-f204-4860-9626-97af3c56f57d/1790303791772-265e6e25-40cd-4595-b7c3-6b4dd51cfb51.jpg"},{"title":"Depth 4 · 비밀의 방","text":"예술과 문명을 지켜내는 수호자. 오래된 물건의 내밀한 사연과 가장 프라이빗한 살롱의 문이 열립니다.","color1":"#F6F1E7","color2":"#CFCBC2","accent":"#B9A77A","effects":["dust"],"imageUrl":"https://pub-c2f2b82ef6164e838c737bb7ed48da65.r2.dev/media/3e54f36a-f204-4860-9626-97af3c56f57d/1790304085214-ed7122bb-2fbd-4a85-a956-e59f57dc93f1.png"},{"title":"Depth 5 · 몽마르트르의 밤","text":"가장 낮은 곳에서 세상을 바라봤지만 누구보다 삶을 애정했던 사람. 있는 그대로의 삶을 기록하며 본질을 아름답게 담아내는, 찬란하게 쓸모없는 존재들의 무대가 열립니다.","color1":"#E2412F","color2":"#1F2A5A","accent":"#F28C28","effects":["embers","stars"],"imageUrl":"https://pub-c2f2b82ef6164e838c737bb7ed48da65.r2.dev/media/3e54f36a-f204-4860-9626-97af3c56f57d/1790304261536-7accb857-7f1f-41d0-b503-d4a3a907abae.jpg"},{"title":"Depth 6 · 예술가의 살롱","text":"무대와 전시로 사일로를 채워 준 모든 예술가들께. 120여 년 전 파리, 자신들만의 작은 공간에서 독립전시회를 열었던 살롱데상의 문이 존경과 응원의 마음으로 활짝 열립니다.","color1":"#3B1A66","color2":"#8E5BD1","accent":"#E0B5FF","effects":["petals","fireflies"],"imageUrl":"https://pub-c2f2b82ef6164e838c737bb7ed48da65.r2.dev/media/3e54f36a-f204-4860-9626-97af3c56f57d/1790304271274-3f2ce0bd-a09d-4f96-bed3-754f91e56e1e.jpg"}]$j$::jsonb) from page_builder p where p.id = m.page_id and p.slug = 'membership' and m.module_type = 'membership_depths';
